export const KOUDAMA_DEFAULT_ICON_ASSIGNMENT: KoudamaIconAssignment =
  KOUDAMA_ICON_ASSIGNMENTS.services ?? {
    featureId: 'services',
    labelAr: 'الخدمات',
    iconSemanticKey: 'services',
    iconName: 'LayoutGrid' as KoudamaIconName,
    signColor: '#1677D2',
    contourColor: '#1677D2',
    tileBackground: '#FFFFFF',
    groupId: 'services',
  };

export function getKoudamaIconAssignment(featureId?: string | null): KoudamaIconAssignment {
  if (!featureId) return KOUDAMA_DEFAULT_ICON_ASSIGNMENT;
  return KOUDAMA_ICON_ASSIGNMENTS[featureId] ?? KOUDAMA_DEFAULT_ICON_ASSIGNMENT;
}
